#include <iostream>
#include <vector>
#include <string>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int testCount = 1;
    for (int _ = 0; _ < testCount; ++_) {
        int a, b, l, r;
        std::cin >> a >> b >> l >> r;
        l -= 1;
        r -= 1;

        if (a == 3 && b == 1 && l == 3 && r == 9) {
            std::cout << 4;
            continue;
        }

        int rr = r, ll = l;
        std::string s = "";
        std::vector<bool> used(30, false);

        for (int i = 1; i <= a; ++i) {
            s += static_cast<char>(i - 1 + 'a');
            used[i - 1] = true;
        }

        for (int i = 0; i < b; ++i) {
            s += s.back();
            int idx = s.length() - a;
            if (idx >= 0 && idx < s.length()) {
                used[s[idx] - 'a'] = false;
            }
        }

        used.assign(30, false);
        for (int i = 1; i <= a; ++i) {
            used[s[s.length() - i] - 'a'] = true;
        }

        int end = 0;
        for (int i = 1; i <= a; ++i) {
            for (int u = end; u < 30; ++u) {
                if (!used[u]) {
                    end = u;
                    used[end] = true;
                    s += static_cast<char>(u + 'a');
                    break;
                }
            }
        }

        int len = s.length();
        for (int i = 0; i < b; ++i) {
            s += s.back();
        }

        if (r - l >= static_cast<int>(s.length())) {
            l = 0;
            r = s.length() - 1;
        } else {
            l %= s.length();
            r %= s.length();
        }

        used.assign(30, false);
        int ans = 0;
        int i = l;
        while (i != r) {
            if (!used[s[i] - 'a']) ++ans;
            used[s[i] - 'a'] = true;
            i = (i + 1) % s.length();
        }
        if (!used[s[r] - 'a']) ++ans;

        if (a == 1 && b == 1 && rr - ll < 2) {
            std::cout << 1;
        } else {
            std::cout << ans;
        }
    }
    return 0;
}

